    slides.sort()
    print('slides', slides)
    ns = {
        'a':'http://schemas.openxmlformats.org/drawingml/2006/main',
        'p':'http://schemas.openxmlformats.org/presentationml/2006/main',
    }
    for s in slides:
        xml = z.read(s)
        root = ET.fromstring(xml)
        texts = []
        for t in root.findall('.//a:t', ns):
            texts.append(t.text)
        if texts:
            print('\n', s)
            for line in texts:
                print('  ', line)
